-- public.wild_near_has(p_world uuid, p_species text, p_x double precision, p_y double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.wild_near_has(p_world uuid, p_species text, p_x double precision, p_y double precision)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  select exists (select 1 from creature c
                  where c.world_id = p_world and c.species = p_species and c.mode = 'wild' and c.keeper is null
                    and c.to_x between p_x - (wild_near() + leg_slack()) and p_x + (wild_near() + leg_slack())
                    and c.to_y between p_y - (wild_near() + leg_slack()) and p_y + (wild_near() + leg_slack())
                    and sqrt(power(creature_x(c) - p_x, 2) + power(creature_y(c) - p_y, 2)) <= wild_near())
$function$
